/**
 * Page-side scripts used by both browser surfaces.
 *
 * Everything here returns plain JSON so results survive CDP serialisation. The
 * selectors are built from tags and `:nth-of-type` rather than class names:
 * class names are generated by build tools and change between deploys, which
 * would make a saved assertion break for no reason.
 */

export interface DomSnapshotNode {
  role: string;
  name: string;
  tag: string;
  selector: string;
  bounds: { x: number; y: number; width: number; height: number };
}

export interface DomSnapshot {
  url: string;
  title: string;
  viewport: { width: number; height: number };
  nodes: DomSnapshotNode[];
  /** Total visible elements considered before the cap was applied. */
  total: number;
  truncated: boolean;
}

export interface ElementPoint {
  ok: boolean;
  reason?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  tag?: string;
  text?: string;
}

export interface VisibilityProbe {
  exists: boolean;
  visible: boolean;
  reason?: string;
  bounds?: { x: number; y: number; width: number; height: number };
}

/**
 * Shared helpers injected into every script: visibility, accessible name and a
 * stable selector path. Kept as a string so it can be embedded in each
 * expression without a build step.
 */
const HELPERS = `
  const isVisible = (el) => {
    if (!el || el.nodeType !== 1) return false;
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none") return false;
    if (Number(style.opacity) === 0) return false;
    if (el.hasAttribute("hidden") || el.getAttribute("aria-hidden") === "true") return false;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    // A fully transparent parent (common in "visibility toggles") still counts as
    // invisible: checkVisibility covers the ancestors in one call where supported.
    if (typeof el.checkVisibility === "function") {
      try {
        if (!el.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) return false;
      } catch {}
    }
    return true;
  };
  const textOf = (el) => {
    const raw = (el.innerText || el.textContent || "").replace(/\\s+/g, " ").trim();
    return raw;
  };
  const labelOf = (el) => {
    const aria = el.getAttribute("aria-label");
    if (aria && aria.trim()) return aria.trim();
    const labelledBy = el.getAttribute("aria-labelledby");
    if (labelledBy) {
      const parts = [];
      for (const id of labelledBy.split(/\\s+/)) {
        const node = document.getElementById(id);
        if (node) parts.push(textOf(node));
      }
      const joined = parts.join(" ").trim();
      if (joined) return joined;
    }
    if (el.labels && el.labels.length) {
      const joined = Array.from(el.labels).map(textOf).join(" ").trim();
      if (joined) return joined;
    }
    return "";
  };
  const nameOf = (el) => {
    const label = labelOf(el);
    if (label) return label;
    const tag = el.tagName.toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select") {
      return (
        el.getAttribute("placeholder") ||
        el.getAttribute("title") ||
        el.getAttribute("name") ||
        el.getAttribute("type") ||
        tag
      ).trim();
    }
    if (tag === "img") return (el.getAttribute("alt") || "").trim();
    return textOf(el);
  };
  const roleOf = (el) => {
    const explicit = (el.getAttribute("role") || "").trim();
    if (explicit) return explicit;
    const tag = el.tagName.toLowerCase();
    if (tag === "a") return el.hasAttribute("href") ? "link" : "text";
    if (tag === "button") return "button";
    if (tag === "select") return "combobox";
    if (tag === "textarea") return "textbox";
    if (tag === "input") {
      const type = (el.getAttribute("type") || "text").toLowerCase();
      if (type === "checkbox" || type === "radio") return type;
      if (type === "submit" || type === "button" || type === "reset") return "button";
      return "textbox";
    }
    if (/^h[1-6]$/.test(tag)) return "heading";
    if (tag === "li") return "listitem";
    if (tag === "table") return "table";
    if (tag === "tr") return "row";
    if (tag === "td" || tag === "th") return "cell";
    return "text";
  };
  const INTERACTIVE = 'a[href],button,input,select,textarea,summary,[role],[onclick],[tabindex]:not([tabindex="-1"])';
  const cssPath = (el) => {
    if (el.id) {
      try {
        if (document.querySelectorAll("#" + CSS.escape(el.id)).length === 1) {
          return "#" + CSS.escape(el.id);
        }
      } catch {}
    }
    const parts = [];
    let node = el;
    while (node && node.nodeType === 1 && node !== document.documentElement) {
      let part = node.tagName.toLowerCase();
      const parent = node.parentElement;
      if (parent) {
        const siblings = Array.from(parent.children).filter((child) => child.tagName === node.tagName);
        if (siblings.length > 1) part += ":nth-of-type(" + (siblings.indexOf(node) + 1) + ")";
      }
      parts.unshift(part);
      if (parts.length >= 7) break;
      node = parent;
    }
    return parts.join(" > ");
  };
  const rectOf = (el) => {
    const rect = el.getBoundingClientRect();
    return { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) };
  };
`;

/**
 * Visible element inventory: interactive controls, headings and text blocks.
 *
 * Only what a user can see is reported, because the questions this answers are
 * "does this account see the delete button" and "what can this account do here".
 * Hidden markup is deliberately excluded — including it would make every account
 * look identical.
 */
export function buildDomSnapshotExpression(options: {
  maxNodes?: number;
  maxNameLength?: number;
} = {}): string {
  const maxNodes = options.maxNodes ?? 400;
  const maxName = options.maxNameLength ?? 120;
  return `(() => {${HELPERS}
    const seen = new Set();
    const nodes = [];
    let total = 0;
    const all = Array.from(document.body ? document.body.querySelectorAll("*") : []);
    for (const el of all) {
      if (!isVisible(el)) continue;
      const role = roleOf(el);
      const interactive = el.matches(INTERACTIVE);
      const heading = /^h[1-6]$/.test(el.tagName.toLowerCase());
      const ownText = Array.from(el.childNodes)
        .filter((node) => node.nodeType === 3)
        .map((node) => node.textContent || "")
        .join(" ")
        .replace(/\\s+/g, " ")
        .trim();
      // Text containers with thousands of children produce noise; keep leaves and
      // elements that own text directly.
      const isTextLeaf = ownText.length > 0 && el.children.length <= 2;
      if (!interactive && !heading && !isTextLeaf) continue;
      const name = nameOf(el).slice(0, ${maxName});
      if (!name && !interactive) continue;
      const selector = cssPath(el);
      if (seen.has(selector)) continue;
      seen.add(selector);
      total += 1;
      if (nodes.length >= ${maxNodes}) continue;
      nodes.push({
        role,
        name,
        tag: el.tagName.toLowerCase(),
        selector,
        bounds: rectOf(el),
      });
    }
    return {
      url: location.href,
      title: document.title,
      viewport: { width: innerWidth, height: innerHeight },
      nodes,
      total,
      truncated: total > nodes.length,
    };
  })()`;
}

/**
 * Resolves an element to viewport coordinates so the caller can click it with
 * real input events. A synthetic `el.click()` does not carry `isTrusted`, and
 * some frameworks ignore untrusted clicks.
 */
export function buildElementPointExpression(selector: string): string {
  const target = JSON.stringify(selector);
  return `(() => {${HELPERS}
    let el;
    try { el = document.querySelector(${target}); } catch { return { ok: false, reason: "invalid-selector" }; }
    if (!el) return { ok: false, reason: "not-found" };
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    el.scrollIntoView({ block: "center", inline: "center", behavior: "instant" });
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return { ok: false, reason: "no-area" };
    return {
      ok: true,
      x: rect.x + rect.width / 2,
      y: rect.y + rect.height / 2,
      width: rect.width,
      height: rect.height,
      tag: el.tagName.toLowerCase(),
      text: nameOf(el).slice(0, 80),
    };
  })()`;
}

/** Focuses a field so the caller can type into it with `Input.insertText`. */
export function buildFocusExpression(selector: string): string {
  const target = JSON.stringify(selector);
  return `(() => {${HELPERS}
    let el;
    try { el = document.querySelector(${target}); } catch { return { ok: false, reason: "invalid-selector" }; }
    if (!el) return { ok: false, reason: "not-found" };
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    if (typeof el.focus === "function") el.focus();
    if (el.disabled || el.readOnly) return { ok: false, reason: "disabled" };
    if (typeof el.select === "function" && typeof el.value === "string") el.select();
    return { ok: true, tag: el.tagName.toLowerCase() };
  })()`;
}

/** Reports whether an element exists and is visible, for assertions. */
export function buildVisibilityExpression(selector: string): string {
  const target = JSON.stringify(selector);
  return `(() => {${HELPERS}
    let el;
    try { el = document.querySelector(${target}); } catch { return { exists: false, visible: false, reason: "invalid-selector" }; }
    if (!el) return { exists: false, visible: false, reason: "not-found" };
    if (!isVisible(el)) return { exists: true, visible: false, reason: "hidden", bounds: rectOf(el) };
    return { exists: true, visible: true, bounds: rectOf(el) };
  })()`;
}

/** Scrolls a tab to the top; used to compare pages from a known position. */
export const RESET_SCROLL_EXPRESSION = "(() => { window.scrollTo(0, 0); return true; })()";

/** Waits for the document to reach a stable size, then reports it. */
export function buildStabilityExpression(): string {
  return `(async () => {
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    let last = -1;
    let stable = 0;
    for (let round = 0; round < 30; round += 1) {
      const height = document.documentElement.scrollHeight;
      if (height === last) stable += 1;
      else { stable = 0; last = height; }
      if (stable >= 2) return { stable: true, height };
      await wait(120);
    }
    return { stable: false, height: last };
  })()`;
}
